import{c as t,Q as a,j as r,m as i}from"./chunks/framework.g_l1frA7.js";const h=JSON.parse('{"title":"Recipes","description":"","frontmatter":{},"headers":[],"relativePath":"guide/recipes.md","filePath":"guide/recipes.md","lastUpdated":null}'),s={name:"guide/recipes.md"};function n(o,e,c,l,p,d){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="recipes" tabindex="-1">Recipes <a class="header-anchor" href="#recipes" aria-label="Permalink to &quot;Recipes&quot;">​</a></h1><p>Trusted, one-click automations for budgets, cleanup, goals, and reviews.</p><h2 id="what-recipes-are" tabindex="-1">What recipes are <a class="header-anchor" href="#what-recipes-are" aria-label="Permalink to &quot;What recipes are&quot;">​</a></h2><p>Recipes are curated action bundles in <code>finsight-agent::recipe_runner</code> — short, reversible sequences the Copilot can propose and you approve. Examples:</p><ul><li>“Roll over unspent groceries to Savings.”</li><li>“Create envelopes from last month’s actuals.”</li><li>“Move $400/month to emergency fund for 6 months.”</li></ul><p>Each recipe lists its steps, expected effects, and required confirmations before it runs.</p><h2 id="running-a-recipe" tabindex="-1">Running a recipe <a class="header-anchor" href="#running-a-recipe" aria-label="Permalink to &quot;Running a recipe&quot;">​</a></h2><ol><li>Open <strong>Recipes</strong> or accept a Copilot-suggested recipe.</li><li>Read the plan — every tool call and its arguments are shown.</li><li>Confirm. The runner executes the sequence via the same RPC dispatcher as every other action and reports per-step results.</li><li>Review the produced transactions/adjustments in the ledger.</li></ol><p>Recipes are <strong>trusted</strong> but not silent — no step runs without your confirmation, and post-execution a review card appears in the Copilot with undo hints where applicable.</p><h2 id="recipes-vs-rules" tabindex="-1">Recipes vs Rules <a class="header-anchor" href="#recipes-vs-rules" aria-label="Permalink to &quot;Recipes vs Rules&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Recipes</th><th>Rules</th></tr></thead><tbody><tr><td>When</td><td>One-off, you trigger it</td><td>Ongoing, matches incoming rows</td></tr><tr><td>Scope</td><td>Multi-step, cross-cutting</td><td>Single pattern → category/treatment</td></tr><tr><td>Review</td><td>Shown as a plan, confirm once</td><td>Enabled/disabled, no per-row confirm</td></tr></tbody></table><p>See also: <a href="/FinSight/automation/rules">Rules</a>, <a href="/FinSight/copilot/recipes">Copilot → Recipes</a>.</p>',12)])])}const g=t(s,[["render",n]]);export{h as __pageData,g as default};
